#!/bin/sh
# Prüft Aufgaben (Zufallsgeneratoren, Lösungen, Geometrie), Merkzettel, Sprache, Oberfläche und Generalprobe.
cd "$(dirname "$0")"
sed -n '/<script>/,/<\/script>/p' ../index.html | sed '1d;$d' > /tmp/lw_check.js
node --check /tmp/lw_check.js && DUP=$(grep -o 'function [A-Za-z0-9_]*' /tmp/lw_check.js | sort | uniq -d) && if [ -n "$DUP" ]; then echo "DOPPELTE FUNKTIONEN: $DUP"; exit 1; else echo 'NAMEN OK'; fi && ALT=$(grep -o 'Hilfslinie[a-z]*\|lange Kante[a-z]*\|langen Kante[a-z]*' /tmp/lw_check.js | sort | uniq -c) && if [ -n "$ALT" ]; then echo "ALTE GEODREIECK-BEGRIFFE: $ALT"; exit 1; else echo 'BEGRIFFE OK'; fi && node run2.js /tmp/lw_check.js && node merkcheck.js /tmp/lw_check.js && node textcheck.js /tmp/lw_check.js && node zahlenraum.js /tmp/lw_check.js | grep -q 'über 1000: 0' && echo 'ZAHLENRAUM OK' && node ui.js ../index.html | grep -v '^OK' && node ui_generalprobe.js ../index.html | grep -v '^OK' && node ui_darstellung.js ../index.html | grep -v '^OK' && node ui_uebungszeit.js ../index.html | grep -v '^OK' && node ui_papier.js ../index.html | grep -v '^OK' && node ui_sicherung.js ../index.html | grep -v '^OK' && node ui_markieren.js ../index.html | grep -v '^OK' && node ui_abgeschlossen.js ../index.html | grep -v '^OK'
